#include <stdio.h>

/* teste do desafio o-leitor-do-diario — counter_protocol (03-tdd 3.9.3).
   Canal retorno: nenhuma captura de stdout. O teste MONTA o diario.txt que
   o aluno vai ler e deixa o numerado.txt vazio antes de chamar — assim os
   dois fopen de leitura nunca devolvem NULL, e quem nao grava nada reprova
   pelo sentinel, sem derrubar o teste. */

/* prototipo da funcao do aluno (o teste declara o que exercita) */
int oLeitorDoDiario(void);

SM_TEST(tres_linhas_numeradas) {
    FILE *entrada = fopen("diario.txt", "w");
    fprintf(entrada, "acordei\nestudei C\ndormi\n");
    fclose(entrada);
    FILE *semente = fopen("numerado.txt", "w");
    fclose(semente);

    checa_int("o leitor devolve 3", oLeitorDoDiario(), 3,
              "o diario tem tres linhas: o fgets le uma por vez ate acabar");

    FILE *f = fopen("numerado.txt", "r");
    char linha[200] = "(nada numerado)";
    fgets(linha, 200, f);
    checa_str("a linha 1 numerada", linha, "1: acordei\n",
              "a primeira linha lida sai com o numero 1 na frente");
    fgets(linha, 200, f);
    checa_str("a linha 2 numerada", linha, "2: estudei C\n",
              "o numero acompanha a ordem em que as linhas foram lidas");
    fgets(linha, 200, f);
    checa_str("a linha 3 numerada", linha, "3: dormi\n",
              "o texto de cada linha sai igual ao do diario, sem perder nada");
    char fim[200] = "(nada numerado)";
    fgets(fim, 200, f);
    checa_str("nao ha linha a mais", fim, "(nada numerado)",
              "o laco para no NULL do fgets: nenhuma linha extra e gravada");
    fclose(f);
}

SM_TEST(um_diario_de_uma_linha_so) {
    FILE *entrada = fopen("diario.txt", "w");
    fprintf(entrada, "so um registro\n");
    fclose(entrada);
    FILE *semente = fopen("numerado.txt", "w");
    fclose(semente);

    checa_int("o leitor devolve 1", oLeitorDoDiario(), 1,
              "o que volta e a contagem do que foi lido, nao um numero fixo");

    FILE *f = fopen("numerado.txt", "r");
    char linha[200] = "(nada numerado)";
    fgets(linha, 200, f);
    checa_str("a unica linha numerada", linha, "1: so um registro\n",
              "com uma linha so, a numeracao comeca e termina no 1");
    fclose(f);
}

