#include <stdio.h>

int oLeitorDoDiario(void) {
    FILE *entrada = fopen("diario.txt", "r");
    if (entrada == NULL) {
        return 0;
    }
    FILE *saida = fopen("numerado.txt", "w");
    if (saida == NULL) {
        fclose(entrada);
        return 0;
    }
    char linha[200] = "";
    int n = 0;
    while (1) {
        if (fgets(linha, 200, entrada) == NULL) {
            break;
        }
        n = n + 1;
        fprintf(saida, "%d: %s", n, linha);
    }
    fclose(saida);
    fclose(entrada);
    return n;
}
